const ELEMENT_PROP_KEYS = new Set(["theme","time","delta","label","flashLabel","freezeAt","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  time: "1:12.408",
  delta: "−0.412",
  label: "Lap time",
  flashLabel: "Fastest lap",
  freezeAt: 42,
  accent: "#3B5BFD",
  fontFamily: "Geist",
  scale: 1,
  delay: 0,
  speed: 1,
};

type SplitFlashElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SplitFlashBase>;

const SplitFlashInner = forwardRef<
  HTMLDivElement,
  SplitFlashElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SplitFlash>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SplitFlashBase
          {...(componentProps as unknown as ComponentProps<typeof SplitFlashBase>)}
        />
      </div>
    </Sequence>
  );
});

export const SplitFlash = Interactive.withSchema({
  Component: SplitFlashInner,
  componentName: "<SplitFlash>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
